              <span className="journey-orbit" aria-hidden="true" />
              <img
                src={stage.image}
                alt={stage.imageAlt}
                width={640}
                height={640}
                loading={index === 0 ? "eager" : "lazy"}
              />
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

export function BrandReel() {
  return (
    <div className="brand-reel" aria-label="Keating mascot and teaching tools">
      <div className="brand-reel-track">
        {[0, 1].map((copy) => (
