import { useNavigate } from "@tanstack/react-router";
import { usePostHog } from "@posthog/react";
import { Nav } from "../components/Nav";
import { Footer } from "../components/Footer";
import { CrtPlaythrough } from "../components/LandingWonder";
import { useSeo } from "../hooks/useSeo";
import { css } from "../../styled-system/css";
import { btnRetro, eyebrow } from "../../styled-system/recipes";

export function Landing() {
  useSeo({
    title: "Keating — The Hyperteacher | Socratic AI Tutor",
    description:
      "Keating is a Socratic teacher for the browser and terminal. Bring a question, explain what you know, and rebuild the idea in your own words.",
    canonical: "https://keating.help/",
  });
  const navigate = useNavigate();
  const posthog = usePostHog();

  return (
    <div className="retro-layout retro-page">
      <Nav />
      <main>
        <section
          className={css({
            paddingBlock: { base: "4.75rem", md: "7.5rem" },
            background:
              "radial-gradient(circle at 76% 36%, color-mix(in srgb, var(--green-wash) 82%, transparent), transparent 24rem), var(--paper)",
          })}
        >
          <div className="wrap">
            <div className={css({ maxWidth: "54rem", marginInline: "auto", textAlign: "center" })}>
              <div className={eyebrow()}>The Hyperteacher</div>
              <h1
                className={css({
                  margin: "1.2rem 0 1rem",
                  fontFamily: "var(--mono-display)",
                  fontSize: { base: "2.6rem", md: "5rem" },
                  fontWeight: 700,
                  lineHeight: 0.98,
                  letterSpacing: "-0.04em",
                })}
              >
                Bring the question. Keep the thinking.
              </h1>
              <p
                className={css({
                  maxWidth: "52ch",
                  margin: "0 auto",
                  color: "var(--ink-soft)",
                  fontSize: { base: "0.98rem", md: "1.08rem" },
                  lineHeight: 1.75,
                })}
              >
                Keating listens to your explanation, finds where it thins out, and asks the next
                useful question. You rebuild the answer and teach it back.
              </p>
              <div
                className={css({
                  display: "flex",
                  justifyContent: "center",
                  flexWrap: "wrap",
                  gap: "1rem",
                  marginTop: "2rem",
                })}
              >
                <button
                  className={btnRetro({ tone: "primary" })}
                  onClick={() => {
                    posthog.capture("start_session_clicked", { source: "landing_hero" });
                    navigate({ to: "/chat" });
                  }}
                >
                  Start a session →
                </button>
                <button className={btnRetro()} onClick={() => navigate({ to: "/download" })}>
                  Install the CLI
                </button>
              </div>
            </div>
          </div>
        </section>

        <CrtPlaythrough />
      </main>
      <Footer />
    </div>
  );
}

